:root {
  --honey-amber: #c8760a;
  --honey-light: #f5c842;
  --honey-pale: #fef3d0;
  --honey-cream: #fdf8ee;
  --bark-brown: #5c3d1e;
  --bark-mid: #8b5e2f;
  --bark-light: #c4956a;
  --green-sage: #6b7c5c;
  --off-white: #fafaf6;
  --border-warm: #d9b87a;
}

article.harvest-log {
  background-color: var(--honey-cream);
  border: 2px solid var(--bark-brown);
  border-radius: 6px;
  width: 460px;
  padding: 0;
  font-size: 14px;
  color: var(--bark-brown);
  overflow: hidden;
}

.log-header {
  display: flex;
  align-items: center;
  gap: 10px;
  background-color: var(--bark-brown);
  padding: 10px 16px;
}

.log-icon {
  font-size: 26px;
  line-height: 1;
}

.log-title-block {
  flex: 1;
}

.log-title {
  font-size: 18px;
  font-weight: 700;
  color: var(--honey-light);
  margin: 0;
  line-height: 1.2;
}

.log-subtitle {
  font-size: 11px;
  color: var(--bark-light);
  margin: 2px 0 0;
  letter-spacing: 0.04em;
}

.log-season {
  background-color: var(--honey-light);
  color: var(--bark-brown);
  font-size: 11px;
  font-weight: 700;
  padding: 3px 10px;
  border-radius: 12px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.log-body {
  padding: 14px 16px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.hive-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
}

.hive-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  background-color: var(--off-white);
  border: 1px solid var(--border-warm);
  border-radius: 5px;
  padding: 8px 6px;
  gap: 2px;
}

.hive-label {
  font-size: 10px;
  color: var(--bark-light);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.hive-number {
  font-size: 20px;
  font-weight: 700;
  color: var(--honey-amber);
  line-height: 1.1;
}

.hive-type {
  font-size: 11px;
  color: var(--green-sage);
  font-weight: 600;
}

.stats-row {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 8px;
}

.stat-block {
  display: flex;
  flex-direction: column;
  align-items: center;
  background-color: var(--honey-pale);
  border: 1px solid var(--border-warm);
  border-radius: 5px;
  padding: 8px 4px;
  margin: 0;
  gap: 2px;
}

.stat-block.highlight {
  background-color: var(--honey-amber);
  border-color: var(--bark-brown);
}

.stat-value {
  font-size: 22px;
  font-weight: 700;
  color: var(--bark-brown);
  line-height: 1;
}

.stat-block.highlight .stat-value {
  color: var(--off-white);
}

.stat-label {
  font-size: 10px;
  color: var(--bark-mid);
  text-align: center;
  line-height: 1.3;
}

.stat-block.highlight .stat-label {
  color: var(--honey-pale);
}

.log-footer {
  display: flex;
  align-items: center;
  background-color: var(--bark-mid);
  padding: 9px 16px;
  gap: 12px;
}

.footer-left,
.footer-mid,
.footer-right {
  display: flex;
  flex-direction: column;
  gap: 1px;
  flex: 1;
}

.footer-label {
  font-size: 10px;
  color: var(--bark-light);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.footer-value {
  font-size: 13px;
  font-weight: 600;
  color: var(--honey-pale);
}

.footer-divider {
  width: 1px;
  height: 32px;
  background-color: var(--bark-light);
  opacity: 0.5;
}
